ALTER TABLE "City" ADD COLUMN "countryCode" TEXT NOT NULL DEFAULT 'KZ';
UPDATE "City" SET "countryCode" = 'RU' WHERE "region" ~* 'росси|russia' OR "name" IN ('Москва', 'Санкт-Петербург', 'Новосибирск', 'Екатеринбург', 'Казань', 'Нижний Новгород', 'Челябинск', 'Самара', 'Омск', 'Ростов-на-Дону', 'Уфа', 'Красноярск', 'Пермь', 'Воронеж', 'Волгоград', 'Краснодар', 'Саратов', 'Тюмень', 'Тольятти', 'Ижевск', 'Барнаул', 'Владивосток', 'Хабаровск', 'Иркутск', 'Оренбург', 'Калининград', 'Сочи', 'Астрахань', 'Махачкала');
ALTER TABLE "Order" ADD COLUMN "currency" TEXT NOT NULL DEFAULT 'KZT';
ALTER TABLE "IntercityRequest" ADD COLUMN "currency" TEXT NOT NULL DEFAULT 'KZT';
ALTER TABLE "RideSharingTrip" ADD COLUMN "currency" TEXT NOT NULL DEFAULT 'KZT';
UPDATE "Order" o SET "currency" = 'RUB' FROM "City" c WHERE o."cityId" = c.id AND c."countryCode" = 'RU';
UPDATE "IntercityRequest" SET "currency" = 'RUB' WHERE split_part("fromCity", ',', 1) IN ('Москва', 'Санкт-Петербург', 'Новосибирск', 'Екатеринбург', 'Казань', 'Нижний Новгород', 'Челябинск', 'Самара', 'Омск', 'Ростов-на-Дону', 'Уфа', 'Красноярск', 'Пермь', 'Воронеж', 'Волгоград', 'Краснодар', 'Саратов', 'Тюмень', 'Тольятти', 'Ижевск', 'Барнаул', 'Владивосток', 'Хабаровск', 'Иркутск', 'Оренбург', 'Калининград', 'Сочи', 'Астрахань', 'Махачкала');
UPDATE "RideSharingTrip" SET "currency" = 'RUB' WHERE split_part("fromCity", ',', 1) IN ('Москва', 'Санкт-Петербург', 'Новосибирск', 'Екатеринбург', 'Казань', 'Нижний Новгород', 'Челябинск', 'Самара', 'Омск', 'Ростов-на-Дону', 'Уфа', 'Красноярск', 'Пермь', 'Воронеж', 'Волгоград', 'Краснодар', 'Саратов', 'Тюмень', 'Тольятти', 'Ижевск', 'Барнаул', 'Владивосток', 'Хабаровск', 'Иркутск', 'Оренбург', 'Калининград', 'Сочи', 'Астрахань', 'Махачкала');
